type Sub = Omit<CancerInput, "kind" | "asOf" | "group" | "parent">;
const colon = (x: Sub): CancerInput => ({ kind: "cancer", asOf, tags: ["subtype-page", "wave4", "colorectal"], ...x, group: "gastrointestinal", parent: "colorectal" });
const kidney = (x: Sub): CancerInput => ({ kind: "cancer", asOf, tags: ["subtype-page", "wave4", "kidney", "rare"], ...x, group: "genitourinary", parent: "rcc" });
const testis = (x: Sub & { parent: string }): CancerInput => ({ kind: "cancer", asOf, tags: ["subtype-page", "wave4", "testicular", "rare"], ...x, group: "genitourinary" });

